(function () {
  var h = hdrs || {};
  // Preferred: the route param cerberus derives from the matched pattern and
  // stamps LAST, after the caller's own headers are copied -- unforgeable.
  var distId = String(h['x-param-distribution_id'] || '');
  if (distId === '') {
    // Fallback, and the reason it is written this way: x-url on a TENANT
    // gateway is /<gateway-id>/<mapping path>, not the path the client sent.
    // Measured, not assumed: POST /d/DIST-PILOT-1/rate arrived as
    // /vwqpwsvi9dms/d/DIST-PILOT-1/rate. Counting from the END is the only
    // form that survives that prefix.
    var u = String(h['x-url'] || '').split('/');
    distId = u.length >= 2 ? u[u.length - 2] : '';
  }
  var p = trg || {};
  function cleanId(v) {
    var s = String(v == null ? '' : v);
    return /^[A-Za-z0-9_-]{1,128}$/.test(s) ? s : '';
  }
  var quoteId = cleanId(p.quote_id);
  var ver = Number(p.version);
  var answers = (p.answers && typeof p.answers === 'object' && !Array.isArray(p.answers)) ? p.answers : {};

  // The contract check. Not a privacy filter: it refuses fields the manifest
  // does not declare because that is schema drift, and drift is how a broker's
  // form and the publisher's schema silently diverge. It also means nothing
  // undeclared can reach the submission record at all.
  var copied = {}, rejected = [], k;
  for (k in answers) {
    if (!Object.prototype.hasOwnProperty.call(answers, k)) continue;
    if (allow.indexOf(k) === -1) { rejected.push(k); continue; }
    copied[k] = answers[k];
  }

  var problems = [];
  if (distId === '') problems.push('no distribution id on the request path');
  if (quoteId === '') problems.push('missing or malformed quote_id');
  if (!isFinite(ver) || ver < 1 || Math.floor(ver) !== ver) problems.push('version must be a positive integer');
  if (rejected.length > 0) problems.push('undeclared fields: ' + rejected.slice(0, 12).join(', '));

  return {
    ok: problems.length === 0,
    problems: problems,
    distribution_id: distId,
    quote_id: quoteId,
    version: isFinite(ver) ? ver : 0,
    quote_reference: String(p.quote_reference || ''),
    submitted_by: String(p.submitted_by || ''),
    origin: (p.origin === 'publisher-renewal') ? 'publisher-renewal' : 'broker-submit',
    selected_products: Array.isArray(p.selected_products) ? p.selected_products : [],
    product_code_list: String(p.product_code_list || (Array.isArray(p.selected_products) ? p.selected_products.join(',') : '')),
    product_version: String(p.product_version || ''),
    answers: copied,
    rejected: rejected,
    broker_filter: JSON.stringify([{ field: 'distribution_id', keyword: distId }]),
    submission_filter: JSON.stringify([{ field: 'quote_id', keyword: quoteId }])
  };
})();

(function () {
  if (!ing.ok) return { action: 'refuse', accepted: false, reason: ing.problems.join('; '), quote_id: ing.quote_id, version: ing.version, submission_id: '' };

  var brows = (brk && brk.results) ? brk.results : [];
  var bseen = {}, buniq = [];
  for (var i = 0; i < brows.length; i++) { var b = brows[i] || {}; if (!b.id || bseen[b.id]) continue; bseen[b.id] = true; buniq.push(b); }
  // The distributor's OWN account id, from the registry -- never the
  // publisher's. On a loopback pilot the two are the same value, so taking it
  // from the wrong place passes every test and mislabels every submission the
  // moment a second distributor exists.
  var acct = String((accounts && accounts[ing.distribution_id]) || '');
  if (acct === '') return { action: 'refuse', accepted: false, reason: 'distribution ' + ing.distribution_id + ' has no account registered', quote_id: ing.quote_id, version: ing.version, submission_id: '' };

  if (buniq.length === 0) return { action: 'refuse', accepted: false, reason: 'no distribution registered as ' + ing.distribution_id, quote_id: ing.quote_id, version: ing.version, submission_id: '' };
  var bd = buniq[0].data || {};
  if (String(bd.broker_status) !== 'active') return { action: 'refuse', accepted: false, reason: 'distribution ' + ing.distribution_id + ' is ' + String(bd.broker_status), quote_id: ing.quote_id, version: ing.version, submission_id: '' };

  var srows = (subs && subs.results) ? subs.results : [];
  var sseen = {}, byVersion = {}, maxV = 0;
  for (var j = 0; j < srows.length; j++) {
    var s = srows[j] || {};
    if (!s.id || sseen[s.id]) continue;
    sseen[s.id] = true;
    var v = Number((s.data && s.data.version) || 0);
    if (v > 0) { byVersion[v] = s.id; if (v > maxV) maxV = v; }
  }

  // (quoteId, version) idempotency, not quoteId alone: a retried submit of the
  // same version returns the submission already minted rather than a second one.
  if (byVersion[ing.version]) {
    return { action: 'replay', accepted: true, reason: 'submission v' + ing.version + ' already exists', quote_id: ing.quote_id, version: ing.version, submission_id: byVersion[ing.version], broker_id: String(bd.broker_id || '') };
  }
  if (ing.version !== maxV + 1) {
    return { action: 'refuse', accepted: false, reason: 'version ' + ing.version + ' is not the next version; the publisher holds v' + maxV, quote_id: ing.quote_id, version: ing.version, submission_id: '' };
  }

  var payload = { quote_id: ing.quote_id, version: ing.version, quote_reference: ing.quote_reference,
    // String(): an all-digit static value reaches the engine as a NUMBER --
    // the flows MCP's jsonValue preprocess JSON.parses any digit-leading
    // string, and the schema wants a string. Same class as the ABN sent as
    // a number that resolved to the wrong entity.
    distributor_account_id: String(acct), received_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
    origin: ing.origin, submitted_by: ing.submitted_by, product_version: ing.product_version,
    product_code_list: ing.product_code_list, selected_products: ing.selected_products };
  var k;
  for (k in ing.answers) { if (Object.prototype.hasOwnProperty.call(ing.answers, k)) payload[k] = ing.answers[k]; }

  return { action: 'create', accepted: true, reason: '', quote_id: ing.quote_id, version: ing.version, submission_id: '', broker_id: String(bd.broker_id || ''), payload: payload };
})();

(function () {
  var rows = (q && q.results) ? q.results : [];
  var seen = {}, best = null;
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i] || {};
    if (!r.id || seen[r.id]) continue;
    seen[r.id] = true;
    if (best === null || Number((r.data && r.data.decision_seq) || 0) > Number((best.data && best.data.decision_seq) || 0)) best = r;
  }
  return { decision_id: best ? best.id : '', found: best !== null };
})();
